import numpy as np
from scipy.optimize import least_squares
def nmse(f,p0):
    best=None
    for s in range(6):
        pp=np.array(p0)*(1+0.3*np.random.randn(len(p0))) if s else np.array(p0,float)
        try:
            r=least_squares(lambda p: f(p)-sigma, pp, max_nfev=3000)
            if best is None or r.cost<best.cost: best=r
        except Exception as e: pass
    return np.mean((f(best.x)-sigma)**2)/np.var(sigma), best.x.round(4)
